def find_union(g, seed, all_sym=True):
 ss=transforms(seed) if all_sym else [next(iter(transforms(seed)))]
 union=set(); placements=[]
 H,W=len(g),len(g[0])
 for s in ss:
  h=max(r for r,c in s)+1; w=max(c for r,c in s)+1
  for i in range(H-h+1):
   for j in range(W-w+1):
    cells={(i+r,j+c) for r,c in s}
    if all(g[r][c]==0 for r,c in cells): union |= cells; placements.append(cells)
 return union,placements
